 async Task QuickInstallLoaderAsync(string loader,string minecraft){if(loader is not("Forge" or "Fabric")||quickLoaderCts!=null)return;if(installing||modBusy||launching||exportCts!=null||game is {HasExited:false}){Status(Loc.Language=="ru"?"Дождись завершения текущей операции и закрой игру.":"Finish the current operation and close the game.",true);return;}
 using var cts=new CancellationTokenSource();quickLoaderCts=cts;installing=true;PlayButton.IsEnabled=false;VersionCombo.IsEnabled=false;DownloadPanel.Visibility=Visibility.Visible;quickLoaderStatus=Loc.Language=="ru"?"Подготовка "+loader:"Preparing "+loader;Status(quickLoaderStatus);SyncBrawlState();bool acceptingProgress=true;string stage="Resolve loader metadata";
 void Stage(string current){if(stage==current)return;stage=current;LoaderLog(loader+" "+minecraft+" · "+stage);}
