 catch(OperationCanceledException)when(cts.IsCancellationRequested){acceptingProgress=false;quickLoaderStatus=Loc.Language=="ru"?"Установка отменена.":"Installation cancelled.";Status(quickLoaderStatus);LoaderLog("CANCELLED "+loader+" "+minecraft+" · "+stage);}
 catch(Exception ex){acceptingProgress=false;quickLoaderStatus=ex is OperationCanceledException?(Loc.Language=="ru"?"Сервер не ответил вовремя. Повтори установку.":"The server timed out. Retry the installation."):ex.Message;LoaderLog("FAILED "+loader+" "+minecraft+" · "+stage+Environment.NewLine+ex);FlushLog();Navigate("Logs");Status(quickLoaderStatus,true);}
 finally{acceptingProgress=false;quickLoaderCts=null;quickLoaderIndeterminate=false;DownloadBar.IsIndeterminate=false;installing=false;VersionCombo.IsEnabled=true;DownloadPanel.Visibility=Visibility.Collapsed;UpdateLaunchButton();SyncBrawlState();}
